import { useState, useEffect } from 'react';
import type { Book } from './types';

// null = loading in progress; Book[] = data ready (may be empty).
// This lets consumers distinguish "not yet fetched" from "fetched, nothing there".
export function App(): JSX.Element {
  const [books, setBooks] = useState<Book[] | null>(null);

  useEffect(() => {
    // Placeholder: replace with real fetch when api.ts is wired up.
    setBooks([]);
  }, []);

  if (books === null) {
    return <div>Loading…</div>;
  }

  return (
    <main>
      {books.map((book) => (
        <div key={book.id}>{book.title}</div>
      ))}
    </main>
  );
}
